1	import 'dart:async';
2	
3	import 'package:cerne/core/network/connectivity_checker.dart';
4	import 'package:cerne/core/network/failure.dart';
5	import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
6	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
8	import 'package:cerne/features/chat/domain/entities/chat_title_deriver.dart';
9	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
10	import 'package:cerne/features/chat/presentation/bloc/chat_event.dart';
11	import 'package:cerne/features/chat/presentation/bloc/chat_state.dart';
12	import 'package:cerne/features/entries/domain/entities/entry.dart';
13	import 'package:cerne/features/entries/domain/usecases/create_entry_usecase.dart';
14	import 'package:flutter_bloc/flutter_bloc.dart';
15	import 'package:fpdart/fpdart.dart';
16	
17	/// The Home/Chat screen's own live conversation — streaming, retry, lazy
18	/// session creation, composer gating (contracts/chat-bloc.md). Depends only
19	/// on `ChatRepository` + `ConnectivityChecker` — never `ChatSessionsBloc`
20	/// nor `SessionBloc` (research.md R7).
21	class ChatBloc extends Bloc<ChatEvent, ChatState> {
22	  ChatBloc({
23	    required ChatRepository chatRepository,
24	    required ConnectivityChecker connectivityChecker,
25	    required CreateEntryUseCase createEntryUseCase,
26	  }) : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
27	       _connectivityChecker = connectivityChecker, // ignore: prefer_initializing_formals
28	       _createEntryUseCase = createEntryUseCase, // ignore: prefer_initializing_formals
29	       super(const ChatLoading()) {
30	    on<ChatStarted>(_onStarted);
31	    on<ConversationSelected>(_onConversationSelected);
32	    on<NewConversationRequested>(_onNewConversationRequested);
33	    on<MessageSubmitted>(_onMessageSubmitted);
34	    on<MessageRetryRequested>(_onMessageRetryRequested);
35	    on<BookmarkTapped>(_onBookmarkTapped);
36	    on<ChatConnectivityChanged>(_onConnectivityChanged);
37	    _connectivitySubscription = connectivityChecker.onConnectivityChanged.listen(
38	      (isOnline) => add(ChatConnectivityChanged(isOnline)),
39	    );
40	  }
41	
42	  final ChatRepository _chatRepository;
43	  final ConnectivityChecker _connectivityChecker;
44	  final CreateEntryUseCase _createEntryUseCase;
45	  late final StreamSubscription<bool> _connectivitySubscription;
46	  final _reauthController = StreamController<void>.broadcast();
47	
48	  /// Guards against a resolved/superseded turn's late emit (defensive,
49	  /// research.md R9) — bumped on every new turn and on every conversation
50	  /// switch/new-conversation request.
51	  int _turnGeneration = 0;
52	
53	  /// A one-shot side effect, not a state (research.md R3/R7) —
54	  /// `HomeChatShellPage` listens to this to raise the "Sessão expirada"
55	  /// overlay.
56	  Stream<void> get reauthRequired => _reauthController.stream;
57	
58	  Future<void> _onStarted(ChatStarted event, Emitter<ChatState> emit) async {
59	    final isOnline = await _connectivityChecker.hasConnection();
60	    final lastId = await _chatRepository.lastActiveSessionId;
61	    if (lastId == null) {
62	      emit(
63	        ChatReady(
64	          sessionId: null,
65	          messages: const [],
66	          isOffline: !isOnline,
67	          awaitingResponse: false,
68	        ),
69	      );
70	      return;
71	    }
72	    await _loadSession(lastId, emit, isOffline: !isOnline);
73	  }
74	
75	  Future<void> _onConversationSelected(
76	    ConversationSelected event,
77	    Emitter<ChatState> emit,
78	  ) async {
79	    _turnGeneration++;
80	    final isOnline = await _connectivityChecker.hasConnection();
81	    await _loadSession(event.sessionId, emit, isOffline: !isOnline);
82	  }
83	
84	  Future<void> _onNewConversationRequested(
85	    NewConversationRequested event,
86	    Emitter<ChatState> emit,
87	  ) async {
88	    _turnGeneration++;
89	    final current = state;
90	    final isOffline = current is ChatReady ? current.isOffline : false;
91	    await _chatRepository.setLastActiveSessionId(null);
92	    emit(
93	      ChatReady(
94	        sessionId: null,
95	        messages: const [],
96	        isOffline: isOffline,
97	        awaitingResponse: false,
98	      ),
99	    );
100	  }
101	
102	  /// One independent request/response per message — never involves
103	  /// `_turnGeneration`, never touches `awaitingResponse`/`messages`, so a
104	  /// save can never block the rest of the screen (FR-006).
105	  Future<void> _onBookmarkTapped(
106	    BookmarkTapped event,
107	    Emitter<ChatState> emit,
108	  ) async {
109	    final current = state;
110	    if (current is! ChatReady) return;
111	
112	    final index = current.messages.indexWhere((m) => m.id == event.messageId);
113	    if (index == -1) return;
114	    final message = current.messages[index];
115	
116	    if (message.role != ChatRole.user) return; // FR-001, defensive
117	    if (message.isOptimistic) return; // research.md R6
118	
119	    final currentStatus = current.bookmarkStatusFor(message.id);
120	    if (currentStatus == BookmarkStatus.saving || currentStatus == BookmarkStatus.saved) {
121	      return; // FR-003/FR-007
122	    }
123	
124	    emit(
125	      current.copyWith(
126	        bookmarks: {...current.bookmarks, message.id: BookmarkStatus.saving},
127	      ),
128	    );
129	
130	    final created = await _createEntryUseCase(
131	      message.content,
132	      EntrySource.chat,
133	      chatMessageId: message.id,
134	      occurredAt: message.createdAt,
135	    );
136	
137	    final latest = state;
138	    if (latest is! ChatReady) return; // navigated away mid-save
139	
140	    await created.match(
141	      (failure) async {
142	        if (failure is AuthExpiredFailure) _reauthController.add(null); // research.md R9
143	        emit(
144	          latest.copyWith(
145	            bookmarks: {...latest.bookmarks, message.id: BookmarkStatus.error},
146	          ),
147	        );
148	      },
149	      (entry) async {
150	        await _chatRepository.recordMessageSaved(
151	          chatMessageId: message.id,
152	          entryId: entry.id,
153	        );
154	        final afterRecord = state;
155	        if (afterRecord is! ChatReady) return;
156	        emit(
157	          afterRecord.copyWith(
158	            bookmarks: {...afterRecord.bookmarks, message.id: BookmarkStatus.saved},
159	          ),
160	        );
161	      },
162	    );
163	  }
164	
165	  void _onConnectivityChanged(
166	    ChatConnectivityChanged event,
167	    Emitter<ChatState> emit,
168	  ) {
169	    final current = state;
170	    if (current is! ChatReady) return;
171	    emit(current.copyWith(isOffline: !event.isOnline));
172	  }
173	
174	  /// The shared fetch-with-cache-fallback path (Clarification 3).
175	  Future<void> _loadSession(
176	    String sessionId,
177	    Emitter<ChatState> emit, {
178	    required bool isOffline,
179	  }) async {
180	    final result = await _chatRepository.listMessages(sessionId);
181	    await result.match(
182	      (failure) async {
183	        if (failure is AuthExpiredFailure) _reauthController.add(null);
184	        final cached = _chatRepository.cachedMessages(sessionId);
185	        if (cached == null) {
186	          // Never opened while online — the "standard no-connection state"
187	          // instead of any content (Edge Cases).
188	          emit(
189	            ChatReady(
190	              sessionId: sessionId,
191	              messages: const [],
192	              isOffline: isOffline,
193	              awaitingResponse: false,
194	              loadFailure: failure,
195	            ),
196	          );
197	        } else {
198	          emit(
199	            ChatReady(
200	              sessionId: sessionId,
201	              messages: cached,
202	              isOffline: isOffline,
203	              awaitingResponse: false,
204	              bookmarks: _seedBookmarks(cached),
205	            ),
206	          );
207	        }
208	      },
209	      (messages) async {
210	        await _chatRepository.setLastActiveSessionId(sessionId);
211	        emit(
212	          ChatReady(
213	            sessionId: sessionId,
214	            messages: messages,
215	            isOffline: isOffline,
216	            awaitingResponse: false,
217	            bookmarks: _seedBookmarks(messages),
218	          ),
219	        );
220	      },
221	    );
222	  }
223	
224	  /// FR-008 — rebuilt from scratch on every `_loadSession` call (never
225	  /// incrementally patched): for every user message already recorded as
226	  /// saved (research.md R1), seed that id as `saved`; every other message is
227	  /// left absent, i.e. `idle`.
228	  Map<String, BookmarkStatus> _seedBookmarks(List<ChatMessage> messages) {
229	    final result = <String, BookmarkStatus>{};
230	    for (final m in messages) {
231	      if (m.role != ChatRole.user) continue;
232	      if (_chatRepository.savedEntryIdFor(m.id) != null) {
233	        result[m.id] = BookmarkStatus.saved;
234	      }
235	    }
236	    return result;
237	  }
238	
239	  Future<void> _onMessageSubmitted(
240	    MessageSubmitted event,
241	    Emitter<ChatState> emit,
242	  ) async {
243	    final current = state;
244	    if (current is! ChatReady || !current.canSend) return;
245	
246	    if (!await _connectivityChecker.hasConnection()) {
247	      // FR-012 — blocked client-side, never attempted. The composer's own
248	      // isOffline flag (R8's live stream) reflects this on its own shortly.
249	      return;
250	    }
251	
252	    final generation = ++_turnGeneration;
253	    final now = DateTime.now();
254	    final optimisticUser = ChatMessage(
255	      id: 'local-${now.microsecondsSinceEpoch}',
256	      sessionId: current.sessionId ?? '',
257	      role: ChatRole.user,
258	      content: event.text,
259	      seq: current.messages.length,
260	      status: ChatMessageStatus.complete,
261	      retryCount: 0,
262	      createdAt: now,
263	    );
264	    final optimisticAssistant = ChatMessage(
265	      id: 'local-${now.microsecondsSinceEpoch}-response',
266	      sessionId: current.sessionId ?? '',
267	      role: ChatRole.assistant,
268	      content: '',
269	      seq: current.messages.length + 1,
270	      status: ChatMessageStatus.streaming,
271	      retryCount: 0,
272	      createdAt: now,
273	    );
274	    emit(
275	      current.copyWith(
276	        messages: [...current.messages, optimisticUser, optimisticAssistant],
277	        awaitingResponse: true,
278	      ),
279	    );
280	
281	    String sessionId;
282	    if (current.sessionId == null) {
283	      final created = await _chatRepository.createSession(
284	        title: ChatTitleDeriver.derive(event.text),
285	      );
286	      if (generation != _turnGeneration) return;
287	      final maybeId = created.match((_) => null, (s) => s.id);
288	      if (maybeId == null) {
289	        final failure = created.getLeft().toNullable()!;
290	        _failTurn(emit, optimisticAssistant.id, failure);
291	        return;
292	      }
293	      sessionId = maybeId;
294	      await _chatRepository.setLastActiveSessionId(sessionId);
295	    } else {
296	      sessionId = current.sessionId!;
297	    }
298	
299	    final stream = _chatRepository.sendMessage(
300	      sessionId: sessionId,
301	      content: event.text,
302	    );
303	    await _consumeTurn(
304	      stream,
305	      emit,
306	      generation: generation,
307	      sessionId: sessionId,
308	      optimisticUserId: optimisticUser.id,
309	      optimisticAssistantId: optimisticAssistant.id,
310	    );
311	  }
312	
313	  Future<void> _onMessageRetryRequested(
314	    MessageRetryRequested event,
315	    Emitter<ChatState> emit,
316	  ) async {
317	    final current = state;
318	    if (current is! ChatReady || current.awaitingResponse) {
319	      return;
320	    }
321	    final index = current.messages.indexWhere(
322	      (m) =>
323	          m.role == ChatRole.assistant &&
324	          m.status == ChatMessageStatus.failed &&
325	          _userMessageIdFor(current.messages, m) == event.userMessageId,
326	    );
327	    if (index == -1) return;
328	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
329	
330	    final userMessage = current.messages[index - 1];
331	    if (userMessage.isOptimistic) {
332	      // The turn's very first `createSession` call failed (FR-006) — there
333	      // is no persisted session/message yet for `retryMessage` to target, so
334	      // re-run the same lazy-creation path `_onMessageSubmitted` takes.
335	      await _retryLazySessionCreation(current, index, userMessage, emit);
336	      return;
337	    }
338	    if (current.sessionId == null) return;
339	
340	    final generation = ++_turnGeneration;
341	    final now = DateTime.now();
342	    final placeholder = ChatMessage(
343	      id: 'local-${now.microsecondsSinceEpoch}-retry',
344	      sessionId: current.sessionId!,
345	      role: ChatRole.assistant,
346	      content: '',
347	      seq: current.messages[index].seq,
348	      status: ChatMessageStatus.streaming,
349	      retryCount: current.messages[index].retryCount + 1,
350	      createdAt: now,
351	    );
352	    final updatedMessages = [...current.messages];
353	    updatedMessages[index] = placeholder;
354	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
355	
356	    final stream = _chatRepository.retryMessage(
357	      sessionId: current.sessionId!,
358	      userMessageId: event.userMessageId,
359	    );
360	    await _consumeTurn(
361	      stream,
362	      emit,
363	      generation: generation,
364	      sessionId: current.sessionId!,
365	      optimisticUserId: null,
366	      optimisticAssistantId: placeholder.id,
367	    );
368	  }
369	
370	  /// Retries a turn whose lazy `createSession` call (FR-010) itself failed
371	  /// before any session ever existed — reuses `createSession` +
372	  /// `sendMessage` with the original user message's own content, exactly as
373	  /// `_onMessageSubmitted` does for a brand-new conversation.
374	  Future<void> _retryLazySessionCreation(
375	    ChatReady current,
376	    int index,
377	    ChatMessage userMessage,
378	    Emitter<ChatState> emit,
379	  ) async {
380	    final generation = ++_turnGeneration;
381	    final now = DateTime.now();
382	    final placeholder = ChatMessage(
383	      id: 'local-${now.microsecondsSinceEpoch}-retry',
384	      sessionId: userMessage.sessionId,
385	      role: ChatRole.assistant,
386	      content: '',
387	      seq: current.messages[index].seq,
388	      status: ChatMessageStatus.streaming,
389	      retryCount: current.messages[index].retryCount + 1,
390	      createdAt: now,
391	    );
392	    final updatedMessages = [...current.messages];
393	    updatedMessages[index] = placeholder;
394	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
395	
396	    final created = await _chatRepository.createSession(
397	      title: ChatTitleDeriver.derive(userMessage.content),
398	    );
399	    if (generation != _turnGeneration) return;
400	    final maybeId = created.match((_) => null, (s) => s.id);
401	    if (maybeId == null) {
402	      final failure = created.getLeft().toNullable()!;
403	      _failTurn(emit, placeholder.id, failure);
404	      return;
405	    }
406	    await _chatRepository.setLastActiveSessionId(maybeId);
407	
408	    final latest = state;
409	    if (latest is! ChatReady || generation != _turnGeneration) return;
410	    emit(latest.copyWith(sessionId: maybeId));
411	
412	    final stream = _chatRepository.sendMessage(
413	      sessionId: maybeId,
414	      content: userMessage.content,
415	    );
416	    await _consumeTurn(
417	      stream,
418	      emit,
419	      generation: generation,
420	      sessionId: maybeId,
421	      optimisticUserId: userMessage.id,
422	      optimisticAssistantId: placeholder.id,
423	    );
424	  }
425	
426	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
427	  /// and a retry.
428	  Future<void> _consumeTurn(
429	    Stream<Either<Failure, ChatStreamEvent>> stream,
430	    Emitter<ChatState> emit, {
431	    required int generation,
432	    required String sessionId,
433	    required String? optimisticUserId,
434	    required String optimisticAssistantId,
435	  }) async {
436	    var assistantId = optimisticAssistantId;
437	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
438	      stream,
439	      onData: (result) {
440	        final latest = state;
441	        if (generation != _turnGeneration || latest is! ChatReady) {
442	          return latest;
443	        }
444	        return result.match((failure) {
445	          if (failure is AuthExpiredFailure) _reauthController.add(null);
446	          return _applyFailure(latest, assistantId, failure);
447	        }, (event) => switch (event) {
448	          MessageCreated() => () {
449	            assistantId = event.assistantMessageId;
450	            return _reconcileIds(
451	              latest,
452	              optimisticUserId,
453	              event.userMessageId,
454	              optimisticAssistantId,
455	              event.assistantMessageId,
456	            );
457	          }(),
458	          ContextReceived() => latest,
459	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
460	          StreamDone(assistantMessageId: final id) =>
461	            _completeMessage(latest, id).copyWith(awaitingResponse: false),
462	        });
463	      },
464	    );
465	    await _reconcileSilentFailure(emit, sessionId, assistantId, generation);
466	  }
467	
468	  /// A failure yielded as (or before) the stream's very first item leaves the
469	  /// bubble `failed` with empty content even though the backend may have
470	  /// kept generating in the background and already persisted the full
471	  /// answer by the time the stream closed (e.g. a transient network drop
472	  /// right after `message_created`, before any token arrives). One
473	  /// best-effort refetch here closes that gap without needing the user to
474	  /// leave and come back. Only acts on an empty-content failure — a failure
475	  /// after partial tokens (FR-005) is left exactly as the stream reported
476	  /// it. Note this is a best-effort recovery for a genuinely slow backend,
477	  /// not a substitute for parsing the stream correctly in the first place —
478	  /// it loses the race whenever the backend is still generating (slow/live
479	  /// answers can take several seconds longer than this one refetch waits
480	  /// for).
481	  Future<void> _reconcileSilentFailure(
482	    Emitter<ChatState> emit,
483	    String sessionId,
484	    String assistantId,
485	    int generation,
486	  ) async {
487	    final seeded = state;
488	    if (seeded is! ChatReady || generation != _turnGeneration) return;
489	    final index = seeded.messages.indexWhere((m) => m.id == assistantId);
490	    if (index == -1) return;
491	    final message = seeded.messages[index];
492	    if (message.status != ChatMessageStatus.failed || message.content.isNotEmpty) {
493	      return;
494	    }
495	
496	    final result = await _chatRepository.listMessages(sessionId);
497	    if (generation != _turnGeneration) return;
498	    result.match((_) {}, (serverMessages) {
499	      ChatMessage? persisted;
500	      for (final m in serverMessages) {
501	        if (m.role == ChatRole.assistant && m.seq == message.seq) {
502	          persisted = m;
503	          break;
504	        }
505	      }
506	      final resolved = persisted;
507	      if (resolved == null ||
508	          resolved.status != ChatMessageStatus.complete ||
509	          resolved.content.isEmpty) {
510	        return;
511	      }
512	      final latest = state;
513	      if (latest is! ChatReady || generation != _turnGeneration) return;
514	      final updated = [
515	        for (final m in latest.messages) if (m.id == assistantId) resolved else m,
516	      ];
517	      emit(latest.copyWith(messages: updated));
518	    });
519	  }
520	
521	  void _failTurn(
522	    Emitter<ChatState> emit,
523	    String assistantId,
524	    Failure failure,
525	  ) {
526	    final latest = state;
527	    if (latest is! ChatReady) return;
528	    emit(_applyFailure(latest, assistantId, failure));
529	  }
530	
531	  /// `null` for a retry's `userMessageId` — a retry never targets an
532	  /// optimistic question, only an already-persisted one.
533	  ChatReady _reconcileIds(
534	    ChatReady current,
535	    String? optimisticUserId,
536	    String realUserId,
537	    String optimisticAssistantId,
538	    String realAssistantId,
539	  ) {
540	    final updated = [
541	      for (final m in current.messages)
542	        if (optimisticUserId != null && m.id == optimisticUserId)
543	          _withId(m, realUserId)
544	        else if (m.id == optimisticAssistantId)
545	          _withId(m, realAssistantId)
546	        else
547	          m,
548	    ];
549	    return current.copyWith(messages: updated);
550	  }
551	
552	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
553	    id: id,
554	    sessionId: message.sessionId,
555	    role: message.role,
556	    content: message.content,
557	    seq: message.seq,
558	    status: message.status,
559	    retryCount: message.retryCount,
560	    createdAt: message.createdAt,
561	  );
562	
563	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
564	    final updated = [
565	      for (final m in current.messages)
566	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
567	    ];
568	    return current.copyWith(messages: updated);
569	  }
570	
571	  // The backend's `done` SSE event carries no authoritative `content`
572	  // (contracts/zod/chat.ts's `sseDoneEventSchema` has only
573	  // `assistantMessageId`/`finishReason`) — the message's own content, built
574	  // up from this turn's `TokenReceived` deltas, is already the full answer.
575	  ChatReady _completeMessage(ChatReady current, String assistantId) {
576	    final updated = [
577	      for (final m in current.messages)
578	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.complete) else m,
579	    ];
580	    return current.copyWith(messages: updated);
581	  }
582	
583	  /// Keeps whatever partial `content` had already accumulated — never
584	  /// removed, hidden, or blanked (FR-005).
585	  ChatReady _applyFailure(
586	    ChatReady current,
587	    String assistantId,
588	    Failure failure,
589	  ) {
590	    final updated = [
591	      for (final m in current.messages)
592	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
593	    ];
594	    return current.copyWith(messages: updated, awaitingResponse: false);
595	  }
596	
597	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
598	    id: message.id,
599	    sessionId: message.sessionId,
600	    role: message.role,
601	    content: content,
602	    seq: message.seq,
603	    status: message.status,
604	    retryCount: message.retryCount,
605	    createdAt: message.createdAt,
606	  );
607	
608	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
609	      ChatMessage(
610	        id: message.id,
611	        sessionId: message.sessionId,
612	        role: message.role,
613	        content: message.content,
614	        seq: message.seq,
615	        status: status,
616	        retryCount: message.retryCount,
617	        createdAt: message.createdAt,
618	      );
619	
620	  /// Position-matching (research.md R10) — the id of the user message
621	  /// immediately preceding [message] in [messages], or `null` if it isn't
622	  /// immediately preceded by one.
623	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
624	    final index = messages.indexWhere((m) => m.id == message.id);
625	    if (index <= 0) return null;
626	    final preceding = messages[index - 1];
627	    return preceding.role == ChatRole.user ? preceding.id : null;
628	  }
629	
630	  @override
631	  Future<void> close() {
632	    unawaited(_connectivitySubscription.cancel());
633	    unawaited(_reauthController.close());
634	    return super.close();
635	  }
636	}
