62	/// Manual `get_it` registration, no code generation (research.md R4).
63	void setupServiceLocator() {
64	  getIt.registerLazySingleton<Dio>(() {
65	    // Bounded timeouts (none were set before) — without them a dropped
66	    // connection never produces a `DioException` at all: `handleResponseStream`
67	    // (dio's stream adapter) skips its per-chunk receive timer entirely when
68	    // `receiveTimeout` is unset, so a radio going down mid-SSE-stream just
69	    // stalls the socket forever instead of surfacing as the `NetworkTimeoutFailure`
70	    // `ApiClient._mapException` already knows how to map.
71	    final dio = Dio(
72	      BaseOptions(
73	        connectTimeout: const Duration(seconds: 15),
74	        sendTimeout: const Duration(seconds: 15),
75	        receiveTimeout: const Duration(seconds: 30),
76	      ),
77	    );
78	    if (kDebugMode) {
79	      // ApiClient maps every DioException to a Failure and never rethrows,
80	      // so without this nothing about a failed call reaches the terminal.
81	      dio.interceptors.add(
82	        LogInterceptor(requestBody: true, responseBody: true, error: true),
83	      );
84	    }
85	    return dio;
86	  });
87	
88	  getIt.registerLazySingleton<SecureTokenStorage>(SecureTokenStorage.new);
89	
90	  getIt.registerLazySingleton<ApiClient>(
91	    () => ApiClient(
92	      dio: getIt<Dio>(),
93	      tokenStorage: getIt<SecureTokenStorage>(),
94	      anonKey: dotenv.env['SUPABASE_ANON_KEY'] ?? '',
95	    ),
96	  );
97	
